options.afterRender:
const box = context.element.querySelector('.vacuum');
const theme = context.grafana.theme;
const rows = context.data || [];

const query = (path, method, columns) => fetch('/api/ds/query', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    from: 'now-5m',
    to: 'now',
    queries: [{
      refId: 'A',
      datasource: { uid: 'roborock' },
      type: 'json',
      source: 'url',
      parser: 'backend',
      format: 'table',
      columns,
      url: '@@ROBOROCK_URL@@' + path,
      url_options: { method, data: '' },
    }],
  }),
});

const send = async (path, done) => {
  const response = await query(path, 'POST', []);
  const body = await response.json().catch(() => ({}));
  const error = body.results && body.results.A && body.results.A.error;
  if (!response.ok || error) {
    context.grafana.notifyError(['Vacuum', error || body.message || response.statusText]);
    return;
  }
  context.grafana.notifySuccess(['Vacuum', done]);
  context.grafana.refresh();
};

const button = (label, color, path, done) => {
  const b = document.createElement('button');
  b.textContent = label;
  b.style.background = color.main;
  b.style.color = color.contrastText;
  b.addEventListener('click', async () => {
    b.disabled = true;
    try { await send(path, done); } finally { b.disabled = false; }
  });
  return b;
};

const programs = document.createElement('div');
programs.className = 'programs';
rows.forEach((row) => programs.append(
  button(row.name, theme.colors.primary, '/routines/' + row.id, row.name + ' started')));
const controls = document.createElement('div');
controls.className = 'controls';
const pause = button('Pause', theme.colors.warning, '/pause', 'Paused');
const resume = button('Resume', theme.colors.success, '/resume', 'Resumed');
pause.disabled = true;
resume.disabled = true;
controls.append(
  pause,
  resume,
  button('Stop', theme.colors.error, '/stop', 'Stopped'),
  button('Return to dock', theme.colors.secondary, '/dock', 'Returning to the dock'));
box.replaceChildren(programs, controls);

const possible = async () => {
  const response = await query('/status', 'GET', [
    { selector: 'can_pause', text: 'can_pause', type: 'boolean' },
    { selector: 'can_resume', text: 'can_resume', type: 'boolean' },
  ]);
  const body = await response.json().catch(() => ({}));
  const frame = body.results && body.results.A && body.results.A.frames && body.results.A.frames[0];
  if (!response.ok || !frame) {
    return {};
  }
  const result = {};
  frame.schema.fields.forEach((field, i) => { result[field.name] = frame.data.values[i][0] === true; });
  return result;
};

possible().then((status) => {
  pause.disabled = !status.can_pause;
  resume.disabled = !status.can_resume;
});

options.styles:
& .vacuum {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

& .programs, & .controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

& button {
  border: 0;
  border-radius: 4px;
  padding: 10px 16px;
  font-size: 15px;
  cursor: pointer;
}

& button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
